// The server object createMcpHandler hands to the factory.
export type McpServer = Parameters<Parameters<typeof createMcpHandler>[0]>[0]

export interface GlobalAuthContext {
  authenticated: true
  tokenId: string
  tokenName: string
  scopes: GlobalMcpScope[]
}

export const authContext = new AsyncLocalStorage<GlobalAuthContext>()

export async function resolveGlobalSchemaToken(rawToken: string): Promise<GlobalAuthContext | null> {
  if (!rawToken?.trim()) return null
  const clean = rawToken.trim()
  const hashed = createHash("sha256").update(clean).digest("hex")

  // Tokens are always hashed on create; plaintext lookup removed 2026-11-23.
  const token = await db.apiToken.findFirst({
    where: { token: hashed, type: "mcp-global-schema" },
    select: { id: true, name: true, permissions: true, expiresAt: true },
  })
  if (!token) return null
  // expiresAt used to be stored but never checked — an expired token kept
  // working indefinitely.
  if (token.expiresAt && token.expiresAt.getTime() <= Date.now()) return null
  const scopes = resolveGlobalMcpScopes(token.permissions)
  if (scopes.length === 0) return null

  db.apiToken
    .updateMany({
      where: { token: hashed, type: "mcp-global-schema" },
      data: { lastUsedAt: new Date() },
    })
    .catch(() => {})

  return { authenticated: true, tokenId: token.id, tokenName: token.name, scopes }
}

export function scopeDenied(toolName: string, required: GlobalMcpScope) {
  return {
    content: [{ type: "text" as const, text: `❌ Token ini tidak punya cakupan '${required}' yang dibutuhkan untuk ${toolName}. Panggil whoami untuk melihat cakupan token, atau minta admin membuat token dengan cakupan yang sesuai.` }],
    structuredContent: { ok: false, code: "FORBIDDEN_SCOPE", requiredScope: required, message: `This token lacks the '${required}' scope required by ${toolName}.` },
    isError: true,
  }
}

// chatgpt8.md P1 ("use one consistent error code"): this used to carry
// neither `structuredContent` nor `isError: true` — on any tool that
// declares an outputSchema (effectively every tool in this file), the MCP
// SDK's validateToolOutput treats a result with no structuredContent AND no
// isError as a malformed SUCCESS and throws its own generic
// "Output validation error: ... no structured content was provided"
// instead of surfacing this unauthorized message at all.
export const UNAUTHORIZED = {
  content: [{
    type: "text" as const,
    text: "❌ Unauthorized: Invalid or missing API token for the SaCMS Global Schema Template MCP server.",
  }],
  structuredContent: { ok: false, code: "UNAUTHORIZED", message: "Invalid or missing API token." },
  isError: true,
}

// Thrown from inside create_website_template's db.$transaction callback
// when a caller-supplied schemaTemplateId doesn't resolve — lets the
// outer catch distinguish "ordinary not-found" from a genuine DB error
// after the transaction has already rolled back.
export class SchemaTemplateNotFoundError extends Error {
  constructor(public readonly id: string) {
    super(`Schema Template '${id}' not found`)
  }
}

// A real, confirmed bug (chatgpt7.md): this used to hardcode "Schema
// Template" regardless of which entity was actually missing — looking up
// a nonexistent Website Template by slug came back saying "Schema
// Template '...' tidak ditemukan", and with no structured `code` at all
// (an agent checking for NOT_FOUND specifically had nothing to match on).
export function notFound(entity: "Schema Template" | "Website Template" | "Global Component", id: string) {
  return {
    content: [{ type: "text" as const, text: `❌ ${entity} '${id}' tidak ditemukan.` }],
    structuredContent: { ok: false, code: "NOT_FOUND", message: `${entity} not found.` },
    isError: true,
  }
}

/**
 * Shared output shape + serializer for get_website_template/
 * create_website_template/update_website_template — all three return the
 * same WebsiteTemplate row shape (Prisma Dates converted to ISO strings,
 * since structuredContent is validated against this zod shape directly,
 * not after a JSON.stringify round-trip that would've done it for free).
 */
/** A change the agent asked for that waits on a human (see
 *  mcp-approvals.ts) — returned as `pendingApprovals` alongside the normal
 *  result, which itself is saved without that change (e.g. as a draft). */
export const APPROVAL_OUTPUT = z.object({ id: z.string(), action: z.string(), status: z.string(), message: z.string() })

/** A bundle file as returned to the agent. `encoding` is only present
 *  ("base64") on binary assets; plain-text files leave it out. */
export const BUNDLE_FILE_OUTPUT = z.object({ path: z.string(), content: z.string(), encoding: z.enum(["utf-8", "base64"]).optional() })
export const FILE_SIZE_OUTPUT = z.object({ path: z.string(), bytes: z.number(), sha256: z.string(), encoding: z.enum(["utf-8", "base64"]).optional() })

export function describeFileSize(f: WebsiteTemplateFile) {
  return {
    path: f.path,
    bytes: bundleFileBytes(f),
    sha256: fileSha256(f.content, f.encoding),
    ...(f.encoding === "base64" ? { encoding: "base64" as const } : {}),
  }
}

