/** The demoDeployment sub-object every create/update_website_template response carries. */
export const DEMO_DEPLOYMENT_OUTPUT_SHAPE = z.object({
  sourceVersion: z.string().nullable().optional(),
  status: z.enum(["ok", "failed", "skipped"]),
  error: z.string().optional(),
  deploymentId: z.string().optional(),
  verified: z.boolean().optional(),
  verificationError: z.string().optional(),
  // Kabar Nusa report P0: `verified` alone can't tell a caller WHICH route
  // failed when the demo has more than one — see verifyDemoRoutes.
  routes: z.array(z.object({ path: z.string(), verified: z.boolean(), error: z.string().optional() })).optional(),
})

export function describeDemoDeployment(demo: { url: string | null; deploymentId?: string; verified?: boolean; verificationError?: string; error?: string; routes?: { path: string; verified: boolean; error?: string }[] }) {
  return demo.url
    ? { status: "ok" as const, deploymentId: demo.deploymentId, verified: demo.verified, verificationError: demo.verificationError, routes: demo.routes }
    : { status: "failed" as const, error: demo.error, deploymentId: demo.deploymentId }
}

// chatgpt8.md P0: create_website_template's `dryRun: true` branch never
// creates or deploys anything, so its response shares no real fields with a
// genuine create's row — it used to be validated against
// WEBSITE_TEMPLATE_OUTPUT_SHAPE (id/name/slug/files/...) regardless, so the
// MCP SDK's output-schema check (server/mcp.js's validateToolOutput, which
// only skips validation when isError is true) rejected EVERY valid dry-run
// result at the protocol layer before it ever reached the calling agent. A
// separate shape — unioned into create_website_template's own outputSchema
// below — instead of cramming both shapes into one object with every field
// optional, which would have let a REAL create response silently pass
// validation while missing fields it's supposed to always have.
export const DRY_RUN_OUTPUT_SHAPE = z.object({
  mode: z.literal("dry_run"),
  ok: z.literal(true),
  valid: z.literal(true),
  issues: z.array(z.object({ path: z.string(), message: z.string() })),
  warnings: z.array(z.object({ path: z.string(), message: z.string() })),
})

/** Returned instead of the normal result when a call runs in the background
 *  (`background: true`, or a dryRun with `verifyBuild: true`). Poll
 *  get_global_operation_status with `operationId`; its `result` then carries the
 *  same structuredContent the synchronous call would have returned. */
export const ASYNC_OPERATION_OUTPUT_SHAPE = z.object({
  mode: z.literal("async"),
  ok: z.literal(true),
  operationId: z.string(),
  status: z.string(),
  message: z.string(),
})

export function asyncOperationResponse(operation: { id: string; status: string }, kind: string) {
  const structured = {
    mode: "async" as const,
    ok: true as const,
    operationId: operation.id,
    status: operation.status,
    message: `${kind} is running in the background. Poll get_global_operation_status with this operationId until status is "succeeded" or "failed".`,
  }
  return { content: [{ type: "text" as const, text: `⏳ ${structured.message}\noperationId: ${operation.id}` }], structuredContent: structured }
}

export type ToolResult = { content: { type: "text"; text: string }[]; structuredContent?: unknown; isError?: boolean }

/** Runs a tool's own (synchronous-mode) handler in the background and
 *  stores its outcome, so a long create/update/redeploy can't be lost to a
 *  dropped connection (audit: ECONNRESET while the template was in fact
 *  created). A result with isError is recorded as a failed operation. */
export async function runToolInBackground(kind: OperationKind, run: () => Promise<ToolResult>) {
  const auth = authContext.getStore()
  const operation = await startBackgroundOperation(kind, auth?.tokenId ?? null, async () => {
    const result = await run()
    return {
      result: result.structuredContent ?? null,
      failed: !!result.isError,
      error: result.isError ? result.content.map((c) => c.text).join("\n") : undefined,
    }
  })
  return asyncOperationResponse(operation, kind)
}

/** Sensitive flags (published: true, isDefault: true, confirmCascade) need
 *  the `publish` scope just to be REQUESTED. */
export function requiresPublishScope(auth: GlobalAuthContext, toolName: string) {
  return auth.scopes.includes("publish") ? null : scopeDenied(`${toolName} (publish/default/cascade)`, "publish")
}

export async function queueApprovals(
  auth: GlobalAuthContext,
  requests: Array<{ action: ApprovalAction; targetId: string; targetName: string; details?: Record<string, unknown> }>,
) {
  const queued: ApprovalSummary[] = []
  for (const request of requests) {
    const row = await requestApproval({ ...request, tokenId: auth.tokenId, tokenName: auth.tokenName })
    queued.push(summarizeApproval(row))
  }
  return queued
}

export function approvalNote(approvals: ApprovalSummary[]) {
  if (!approvals.length) return ""
  return `\n\n⏳ Menunggu persetujuan admin di dashboard (/admin/developer/approvals):\n${approvals.map((a) => `- ${a.action} (id: ${a.id})`).join("\n")}`
}

/** A schema template's own internal demo workspace (real data + API key) to
 *  build a dryRun bundle against, or null when there isn't one yet. */
export async function findDemoTenantForSchemaTemplate(idOrSlug: string) {
  const template = await db.schemaTemplate.findFirst({ where: { OR: [{ id: idOrSlug }, { slug: idOrSlug }] }, select: { id: true, demoTenantId: true } })
  if (!template) return null
  const { findSchemaDemoWorkspace } = await import("@/lib/infrastructure/demo-tenant")
  return findSchemaDemoWorkspace(db, template)
}

/** dryRun + verifyBuild: the static checks already passed; the real
 *  sandbox build runs in the background (see verifyBundleBuild). A build
 *  or render failure is recorded as a failed operation. */
export function runVerifyBuild(
  files: { path: string; content: string; encoding?: "utf-8" | "base64" }[],
  demoTenant: { id: string; slug: string } | null,
  warnings: { path: string; message: string }[],
) {
  return runToolInBackground("verify_build", async () => {
    const { verifyBundleBuild } = await import("@/lib/infrastructure/deploy-website-template-demo")
    const verification = await verifyBundleBuild(files, demoTenant)
    const failed = verification.status !== "passed" && verification.status !== "skipped"
    return {
      content: [{ type: "text" as const, text: verification.message }],
      structuredContent: { mode: "dry_run_build", ok: !failed, ...verification, warnings },
      isError: failed,
    }
  })
}

export function invalidSchema(error: z.ZodError) {
  const issues = error.issues.map((i) => ({ path: formatZodPath(i.path), message: i.message }))
  return {
    content: [{
      type: "text" as const,
      text: `❌ Schema tidak valid:\n${issues.map((i) => `- ${i.path}: ${i.message}`).join("\n")}`,
    }],
    structuredContent: { ok: false, code: "VALIDATION_FAILED", issues, message: `${issues.length} validation issue(s) found.` },
    isError: true,
  }
}

/** Advisory-only issues (componentSlugs typo, missing title-source for a
 *  slug field, an unrecognized dummyData key, ...) never block a save —
 *  surfaced here as a plain text note instead, since none of these tools'
 *  success outputSchemas declare a `warnings` field of their own (only
 *  create_website_template's dry-run shape does). */
export function warningsNote(warnings: { path: string; message: string }[]): string {
  if (warnings.length === 0) return ""
  return `\n\n⚠️ ${warnings.length} catatan (tidak memblokir penyimpanan):\n${warnings.map((w) => `- ${w.path}: ${w.message}`).join("\n")}`
}

export function referenceIssuesResponse(issues: { path: string; message: string }[]) {
  return {
    content: [{ type: "text" as const, text: `❌ Ditemukan ${issues.length} masalah referensi/opsi:\n${issues.map((i) => `- ${i.path}: ${i.message}`).join("\n")}` }],
    structuredContent: { ok: false, code: "VALIDATION_FAILED", issues, message: `${issues.length} validation issue(s) found.` },
    isError: true,
  }
}

